func TestStream_ReplayAndAck(t *testing.T) {
	srv, cleanup := setupTestServer(t)
	defer cleanup()

	// 1. Ingest event 1
	rec1 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec1, httptest.NewRequest(http.MethodPost, "/v1/ingest/test_open", bytes.NewReader([]byte(`{"order":1}`))))
	evt1ID := rec1.Header().Get("X-Event-ID")

	// 2. Ingest event 2
	rec2 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec2, httptest.NewRequest(http.MethodPost, "/v1/ingest/test_open", bytes.NewReader([]byte(`{"order":2}`))))
	evt2ID := rec2.Header().Get("X-Event-ID")

	// 3. Connect to stream with Last-Event-ID = evt1ID, using a context that cancels after 50ms
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	streamReq := httptest.NewRequest(http.MethodGet, "/v1/stream?channel=test_open", nil).WithContext(ctx)
	streamReq.Header.Set("Last-Event-ID", evt1ID)
	streamRec := httptest.NewRecorder()

	srv.Routes().ServeHTTP(streamRec, streamReq)

	streamOutput := streamRec.Body.String()
	if !strings.Contains(streamOutput, evt2ID) {
		t.Errorf("expected stream replay to contain evt2 (%s), got:\n%s", evt2ID, streamOutput)
	}
	if strings.Contains(streamOutput, evt1ID) {
		t.Errorf("stream replay should not contain already processed evt1 (%s)", evt1ID)
	}

	// 4. Test Ack for evt2
	ackReq := httptest.NewRequest(http.MethodPost, "/v1/events/"+evt2ID+"/ack", nil)
	ackRec := httptest.NewRecorder()
	srv.Routes().ServeHTTP(ackRec, ackReq)

	if ackRec.Code != http.StatusOK {
		t.Errorf("expected 200 OK for ack, got %d", ackRec.Code)
	}
	if !strings.Contains(ackRec.Body.String(), `"status":"acked"`) {
		t.Errorf("expected status acked in body, got %s", ackRec.Body.String())
	}
}

