	tmpDir := t.TempDir()
	scriptContent := `
function handle(req, env) {
    var data = JSON.parse(req.body);
    if (!data.signature || data.signature !== env.SECRET) {
        return { accept: false, status: 401, error: "Assinatura invalida" };
    }
    return { accept: true };
}
`
	scriptPath := filepath.Join(tmpDir, "validate.js")
	_ = os.WriteFile(scriptPath, []byte(scriptContent), 0644)

