	srv := NewServer(cfg, store, engine.New(tmpDir), sse.New())

	// 1. Send invalid signature -> 401
	rec1 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec1, httptest.NewRequest(http.MethodPost, "/v1/ingest/chan_mw", bytes.NewReader([]byte(`{"signature":"errada"}`))))
